<script setup lang="ts">
import type {ScopedCredential,ScopedCategory} from '~~/shared/utils/vault-sources'
const props=defineProps<{entry:ScopedCredential;categories:ScopedCategory[];busy:boolean}>()
const emit=defineEmits<{open:[entry:ScopedCredential];edit:[entry:ScopedCredential];favorite:[entry:ScopedCredential];delete:[entry:ScopedCredential]}>()
const {groups,domain,safeUrl}=useCredentialTile(props)
</script>
<template><article class="credential-tile"><button class="credential-tile-open" :aria-label="`Открыть карточку: ${entry.title}`" @click="emit('open',entry)"><span class="tile-avatar"><img v-if="entry.images?.[0]" :src="entry.images[0].data" alt=""/><span v-else>{{ entry.title.slice(0,1).toUpperCase() }}</span></span><h3>{{ entry.title }}</h3><span class="tile-domain">{{ domain }}</span><div class="tile-groups"><span v-for="(name,i) in groups.slice(0,2)" :key="i" :title="name"><UIcon name="i-lucide-vault"/>{{ name }}</span><span v-if="groups.length>2">+{{ groups.length-2 }}</span></div><div class="tile-categories"><span v-for="category in categories.slice(0,2)" :key="category.filterId">{{ category.name }}</span><span v-if="categories.length>2">+{{ categories.length-2 }}</span></div></button><footer><a v-if="safeUrl(entry.url)" :href="safeUrl(entry.url)" target="_blank" rel="noopener noreferrer" :aria-label="`Открыть сайт: ${entry.title}`"><UIcon name="i-lucide-external-link"/></a><span v-else/><div><button :class="{'is-favorite':entry.favorite}" :disabled="busy" :aria-label="entry.favorite?'Убрать из избранного':'В избранное'" @click="emit('favorite',entry)"><UIcon name="i-lucide-star"/></button><button :disabled="busy" aria-label="Изменить карточку" @click="emit('edit',entry)"><UIcon name="i-lucide-pencil"/></button><button :disabled="busy" aria-label="Удалить карточку" @click="emit('delete',entry)"><UIcon name="i-lucide-trash-2"/></button></div></footer></article></template>
